import json,sys
raw=sys.stdin.read()
# strip banner if present
i=raw.find('[')
try:
    d=json.loads(raw[i:] if i>=0 else raw)
except: 
    d=json.loads(raw)
def show(n):
    print(n.get('id'),'|',n.get('status'),'| owner:',n.get('owner'))
    s=n.get('strategy') or n.get('note') or n.get('description') or ''
    if s: print('  ',s[:900])
if isinstance(d,list):
    for n in d: show(n)
elif isinstance(d,dict):
    show(d)
    for c in d.get('children',[]): show(c)
